@pytest.mark.asyncio
async def test_greeting_only_routes_to_ai(monkeypatch):
    monkeypatch.setattr(
        "backend.services.integrations.whatsapp_triage_service.settings.whatsapp_personal_contacts",
        "",
    )
    monkeypatch.setattr(
        "backend.services.integrations.whatsapp_triage_service.settings.whatsapp_allowed_numbers",
        "",
    )

    service = WhatsAppTriageService()

    decision, reason = await service.should_escalate(
        phone="6282264599868",
        message_text="Hi",
        sender_name="Test",
    )

    assert decision == TriageDecision.BOT_CAN_HANDLE
    assert reason == "greeting_only"
